void scale(float* x, size_t n, float g) {
    __m256 vg = _mm256_set1_ps(g);
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        __m256 v = _mm256_load_ps(x + i);
        _mm256_storeu_ps(x + i, _mm256_mul_ps(v, vg));
    }
    for (; i < n; ++i) x[i] *= g;
}

