void cmul(const float* a, const float* b, float* c, size_t n) {
    for (size_t i = 0; i < 2 * n; i += 8) {        // 4 complex per iter
        __m256 va = _mm256_loadu_ps(a + i);        // ar0 ai0 ar1 ai1 ...
        __m256 vb = _mm256_loadu_ps(b + i);        // br0 bi0 br1 bi1 ...
        __m256 br = _mm256_moveldup_ps(vb);        // br0 br0 br1 br1 ...
        __m256 bi = _mm256_movehdup_ps(vb);        // bi0 bi0 bi1 bi1 ...
        __m256 sw = _mm256_permute_ps(va, 0xB1);   // ai0 ar0 ai1 ar1 ...
        __m256 t2 = _mm256_mul_ps(sw, bi);         // ai*bi  ar*bi
        // even lanes: ar*br - ai*bi, odd lanes: ai*br + ar*bi
        __m256 r = _mm256_fmaddsub_ps(va, br, t2);
        _mm256_storeu_ps(c + i, r);
    }
}
